  "(PDF attached: {file})": "(PDF adjunto: {file})",
  "Performance: the band performs live at the event on the date and times agreed.": "Actuación: la banda actúa en directo en el evento en la fecha y el horario acordados.",
  "Fee & payment: a deposit confirms the booking; the balance is due on the event date. The deposit is non-refundable if the client cancels.": "Caché y pago: una señal confirma la reserva; el resto se abona el día del evento. La señal no se devuelve si el cliente cancela.",
  "Cancellation: if the client cancels less than 30 days before the event, the full fee is due.": "Cancelación: si el cliente cancela con menos de 30 días de antelación, se abona el caché completo.",
  "Venue: the client provides safe access for load-in, a stage area, power near the stage and a secure place for equipment.": "Lugar: el cliente facilita un acceso seguro para la carga, una zona de escenario, corriente cerca del escenario y un lugar seguro para el equipo.",
  "Hospitality: meals and soft drinks for the band and crew, plus parking for the band vehicles.": "Hospitalidad: comidas y refrescos para la banda y el equipo, además de aparcamiento para los vehículos de la banda.",
  "Breaks & overtime: sets include short breaks; extra time on the day is charged at the agreed rate.": "Pausas y horas extra: los pases incluyen pausas breves; el tiempo extra del día se cobra a la tarifa acordada.",
  "Recordings: no professional audio or video recording without the band’s written consent.": "Grabaciones: no se permite grabación profesional de audio o vídeo sin el consentimiento escrito de la banda.",
  "Force majeure: neither party is liable for cancellations caused by events beyond their control.": "Fuerza mayor: ninguna de las partes es responsable de cancelaciones por causas ajenas a su control.",
  "Stage: minimum 6 × 4 m, level and covered if outdoors.": "Escenario: mínimo 6 × 4 m, nivelado y cubierto si es al aire libre.",
  "Power: two separate 16 A outlets on the stage, on a circuit not shared with catering or lighting.": "Corriente: dos tomas independientes de 16 A en el escenario, en un circuito no compartido con catering ni iluminación.",
  "Sound: PA suited to the room with monitor mixes for each musician, or time to set up the band’s own system.": "Sonido: equipo adecuado a la sala con mezclas de monitor para cada músico, o tiempo para montar el equipo de la banda.",
  "Times: access for load-in and setup 2 hours before the start; soundcheck before guests arrive.": "Horarios: acceso para carga y montaje 2 horas antes del inicio; prueba de sonido antes de que lleguen los invitados.",
  "Backstage: a private, lockable room with mirror, seating and water.": "Camerino: una sala privada con llave, espejo, asientos y agua.",
  "Hospitality: meals and soft drinks for the band and crew.": "Hospitalidad: comidas y refrescos para la banda y el equipo.",
  "Parking: spaces for the band vehicles close to the loading point.": "Aparcamiento: plazas para los vehículos de la banda cerca del punto de carga.",
