  "Notes, suggestions or a setlist order made on this phone haven’t reached the band yet. Send them before you sign out: “Sign out anyway” deletes them from this phone.": "Notas, sugerencias o un orden de setlist hechos en este teléfono aún no han llegado a la banda. Envíalos antes de cerrar sesión: «Cerrar sesión igualmente» los borra de este teléfono.",
  "Notes, suggestions or a setlist order made on this phone haven’t reached the band yet. “Sign out” keeps them on this phone for your account, with the refused changes.": "Notas, sugerencias o un orden del setlist hechos en este teléfono aún no han llegado a la banda. «Cerrar sesión» los guarda en este teléfono para tu cuenta, con los cambios rechazados.",
  "Notes, suggestions or a setlist order made on this phone haven’t reached the band yet. “Sign out anyway” keeps them on this phone, and they’re sent when you sign in again.": "Notas, sugerencias o un orden de setlist hechos en este teléfono aún no han llegado a la banda. «Cerrar sesión igualmente» los guarda en este teléfono y se envían cuando vuelvas a iniciar sesión.",
