  "Try another name or word.": "Prueba con otro nombre o palabra.",
  "The forum opens in its own window. Right-click a song or a playlist, choose Copy Link and tap Paste link here, or drag the link onto this box.": "El foro se abre en su propia ventana. Haz clic derecho en una canción o una lista, elige Copiar enlace y toca Pegar enlace aquí, o arrastra el enlace a este recuadro.",
  "Paste link": "Pegar enlace",
  "Drop the link here": "Suelta aquí el enlace",
  "Your browser blocked the forum window. Allow pop-ups for BandWith and try again.": "Tu navegador bloqueó la ventana del foro. Permite las ventanas emergentes para BandWith y vuelve a intentarlo.",
  "The clipboard has no iReal Pro link: copy one in the forum first.": "El portapapeles no tiene un enlace de iReal Pro: copia uno en el foro primero.",
  "This change wasn't saved: band gear is managed by the admins, personal gear by its owner.": "Este cambio no se guardó: el equipo de la banda lo gestionan los admins; el personal, su dueño.",
  "Personal · {name}": "Personal · {name}",
  "Items with a lock belong to the band or to another member: only the admins or their owner can change them.": "Los artículos con candado son de la banda o de otro miembro: solo los admins o su dueño pueden cambiarlos.",
  "Band gear: only the admins can change it.": "Equipo de la banda: solo los admins pueden cambiarlo.",
  "Only {name} and the admins can change this item.": "Solo {name} y los admins pueden cambiar este artículo.",
  "A member": "Un miembro",
  "Add my gear": "Añadir mi equipo",
  "Belongs to": "De quién es",
  "The band": "La banda",
  "Me (personal)": "Mío (personal)",
  "Personal gear: the band sees it, only you and the admins can change it.": "Equipo personal: la banda lo ve, solo tú y los admins podéis cambiarlo.",
  "When an inquiry comes in, tap + and choose \"New quote\". The system calculates travel, lineup compensation, taxes, and deposit schedules automatically.": "Cuando llegue una solicitud, toca + y elige \"Presupuesto\". El sistema calcula automáticamente desplazamientos, cachés de la formación, impuestos y plazos de los anticipos.",
  "You are all set! You can open \"Pricing, fees & services\" at any time from the Settings tab to set your currency, rates, and services.": "¡Todo listo! Puedes abrir \"Precios, cachés y servicios\" cuando quieras desde la pestaña Ajustes para configurar moneda, tarifas y servicios.",
  "Access anytime from Settings → Pricing, fees & services": "Accede cuando quieras desde Ajustes → Precios, cachés y servicios",
  "Personal gigs stay private": "Los bolos personales son privados",
  "Only you see their title and venue. Bands only see that you’re busy.": "Solo tú ves el título y el lugar. Las bandas solo ven que estás ocupado.",
  "Permanently removes your profile, personal gigs and direct messages. Your messages in band, gig and group chats stay, shown as from a former member. If you are the only admin of a band with other members, make someone else admin first; bands where you are alone are deleted with your account.": "Elimina para siempre tu perfil, bolos personales y mensajes privados. Tus mensajes en los chats de la banda, de los bolos y de grupo se quedan, como de un antiguo miembro. Si eres el único admin de una banda con otros miembros, nombra antes a otro admin; las bandas en las que estás solo se eliminan con tu cuenta.",
  "All workspace data is encrypted in transit and at rest. Built for musicians, managers, and touring crews.": "Todos los datos del espacio de trabajo están cifrados en tránsito y en reposo. Creado para músicos, mánagers y equipos de gira.",
  "v{version} · Encrypted in transit and at rest": "v{version} · Cifrado en tránsito y en reposo",
  "Encrypted in transit and at rest": "Cifrado en tránsito y en reposo",
  "Client paid": "Pagado por el cliente",
  "Client unpaid": "Sin pagar por el cliente",
